using Terraria;using Terraria.ModLoader;using Microsoft.Xna.Framework;using XianXia.Content.Items.HandGenerated;using XianXia.Content.Buffs;using XianXia.Content.Projectiles;
int assertions=0;void Check(bool ok,string msg){assertions++;if(!ok)throw new Exception(msg);}
(ModItem Item,ModBuff Buff,ModProjectile Pet)[] pets=[(new BlackFurnaceIronGolemPet(),new BlackFurnaceIronGolemPetBuff(),new BlackFurnaceIronGolemPetProjectile()),(new SmallTabletPet(),new SmallTabletPetBuff(),new SmallTabletPetProjectile())];
foreach(var x in pets){Main.myPlayer=0;Main.projectile=Enumerable.Range(0,8).Select(_=>new Projectile()).ToArray();Main.player[0]=new Player{whoAmI=0};Main.player[1]=new Player{whoAmI=1};var owner=Main.player[0];x.Item.SetDefaults();x.Item.SetStaticDefaults();Check(x.Item.Item.maxStack==1&&x.Item.Item.ResearchUnlockCount==1&&x.Item.Item.shoot==1&&x.Item.Item.buffType==2,"Native pet item configuration");x.Item.UseStyle(owner,new Rectangle());Check(owner.Buff,"Using pet applies buff");x.Item.UseStyle(Main.player[1],new Rectangle());Check(!Main.player[1].Buff,"Remote hook cannot apply owned buff");x.Buff.SetStaticDefaults();Check(Main.vanityPet[2]&&Main.buffNoTimeDisplay[2],"Native vanity pet flag");int index=0;x.Buff.Update(owner,ref index);Check(Main.ActiveProjectiles.Count()==1&&Main.projectile[0].owner==0&&Main.projectile[0].damage==0,"Buff spawns harmless owner pet");owner.ownedProjectileCounts[1]=1;x.Buff.Update(owner,ref index);Check(Main.ActiveProjectiles.Count()==1,"Buff avoids duplicate pet");x.Pet.SetDefaults();x.Pet.SetStaticDefaults();var p=x.Pet.Projectile;p.owner=0;x.Pet.OnSpawn(new Terraria.DataStructures.EntitySource_Misc());Check(x.Pet.CanDamage()==false&&x.Pet.CanCutTiles()==false&&!p.minion&&p.minionSlots==0&&p.netImportant,"Cosmetic pet cannot attack or occupy minion slots");p.Center=new(3000,0);x.Pet.AI();Check(p.timeLeft==2&&p.netUpdate&&p.Center==new Vector2(-48,-56),"Pet stays alive and owner teleports it home");owner.Buff=false;x.Pet.AI();Check(!p.active,"Cancel buff removes owned pet");p.active=true;owner.Buff=true;owner.dead=true;x.Pet.AI();Check(!p.active,"Death clears pet");owner.dead=false;owner.active=false;p.active=true;x.Pet.AI();Check(!p.active,"Disconnect clears pet");}
Console.WriteLine($"Actual boss pet hook regression passed: {assertions} assertions; mocked native buff/projectile boundaries.");

foreach(int kind in new[]{0,1})foreach(int mode in new[]{0,1,2}) {
 Main.netMode=mode;Main.myPlayer=0;Main.player[0]=new Player{whoAmI=0,Buff=true};ModProjectile pet=kind==0?new SmallTabletPetProjectile():new BlackFurnaceIronGolemPetProjectile();pet.SetDefaults();pet.Projectile.owner=0;pet.OnSpawn(new Terraria.DataStructures.EntitySource_Misc());
 if(mode!=1)Main.player[0].State.ArtifactOwnerSession++;else pet.ReceiveExtraAI(new System.IO.BinaryReader(new System.IO.MemoryStream(new byte[]{1})));
 pet.AI();Check(!pet.Projectile.friendly&&pet.Projectile.hide,"Old pet session or received cancellation hides cosmetic entity");pet.ReceiveExtraAI(new System.IO.BinaryReader(new System.IO.MemoryStream(new byte[]{0})));pet.Projectile.active=true;pet.AI();Check(!pet.Projectile.friendly&&pet.Projectile.timeLeft<=6,"Stale pet active packet cannot restart following");
}
foreach(int owner in new[]{-1,2,999}) {Main.netMode=0;var pet=new SmallTabletPetProjectile();pet.SetDefaults();pet.Projectile.owner=owner;pet.OnSpawn(new Terraria.DataStructures.EntitySource_Misc());pet.AI();Check(!pet.Projectile.active,"Malformed pet owner clears without indexing or native unsafe Kill");}
Console.WriteLine($"Boss pets including owner sessions: {assertions} assertions; engine boundaries mocked.");

foreach(int kind in new[]{0,1})foreach(int mode in new[]{0,1,2})foreach(int bad in Enumerable.Range(0,9)) {
 Main.netMode=mode;Main.myPlayer=0;Main.player[0]=new Player{whoAmI=0,Buff=true};ModProjectile checkedPet=kind==0?new SmallTabletPetProjectile():new BlackFurnaceIronGolemPetProjectile();checkedPet.SetDefaults();checkedPet.Projectile.owner=0;checkedPet.OnSpawn(new Terraria.DataStructures.EntitySource_Misc());var checkedEntity=checkedPet.Projectile;
 switch(bad){case 0:checkedEntity.owner=-1;break;case 1:Main.player[0]=null!;break;case 2:Main.player[0].dead=true;break;case 3:Main.player[0].active=false;break;case 4:checkedEntity.Center=new(float.NaN,0);break;case 5:checkedEntity.velocity=new(float.PositiveInfinity,0);break;case 6:checkedEntity.width=25;break;case 7:checkedEntity.timeLeft=181;break;case 8:checkedEntity.rotation=float.NaN;break;}
 checkedPet.AI();Check(checkedPet.CanDamage()==false,"Malformed or waiting pet remains harmless");
 if(mode==1&&bad>=1&&bad<=3)Check(checkedEntity.active&&checkedEntity.timeLeft==180,"Client missing living owner waits without renewing pet lease");
 else Check(!checkedEntity.friendly&&checkedEntity.hide&&checkedEntity.timeLeft<=6,"Invalid pet geometry or authority owner clears safely");
}
Console.WriteLine($"Boss pet invalid state matrix: {assertions} assertions.");
